# Parse the graph to find all edges from 8f14e45fce
edges = context.strip().split('\n')
source_node = '8f14e45fce'
depth_1_nodes = []

for line in edges:
    if ' -> ' in line:
        parts = line.split(' -> ')
        if len(parts) == 2:
            src, dst = parts[0].strip(), parts[1].strip()
            if src == source_node:
                depth_1_nodes.append(dst)

print(f"Edges from {source_node}:")
for node in depth_1_nodes:
    print(f"  {source_node} -> {node}")

print(f"\nTotal nodes at depth 1: {len(depth_1_nodes)}")
print(f"Unique nodes at depth 1: {sorted(set(depth_1_nodes))}")
